<?php
require_once __DIR__.'/../includes/functions.php';require_admin();$pdo=db();$page_title='Quest Management';
if($_SERVER['REQUEST_METHOD']==='POST'&&verify_csrf($_POST['csrf']??null)){$id=(int)$_POST['id'];$action=$_POST['action']??'';if($action==='cancel'){$pdo->prepare("UPDATE quests SET status='cancelled' WHERE id=? AND status<>'completed'")->execute([$id]);flash('success','Quest cancelled.');}elseif($action==='delete'){$pdo->prepare("DELETE FROM quests WHERE id=?")->execute([$id]);flash('success','Quest deleted.');}redirect('admin/quests.php');}
$quests=$pdo->query("SELECT q.id,q.title,q.status,q.reward_amount,q.xp_reward,q.created_at,u.username creator,c.name category,(SELECT COUNT(*) FROM quest_participants qp WHERE qp.quest_id=q.id) participants FROM quests q JOIN users u ON u.id=q.creator_id JOIN categories c ON c.id=q.category_id ORDER BY q.created_at DESC")->fetchAll();require __DIR__.'/../includes/header.php';
?><div class="admin"><div class="page-head compact"><div><span class="eyebrow">ADMINISTRATION</span><h1>QUEST MANAGEMENT.</h1><p>Review, inspect, and moderate posted missions.</p></div></div><div class="admin-table"><?php foreach($quests as $q):?><div class="admin-row"><div><b><a href="<?=base_url('quest.php?id='.(int)$q['id'])?>"><?=e($q['title'])?></a></b><small><?=e($q['category'])?> · by <?=e($q['creator'])?> · <?=e($q['participants'])?> participants · +<?=e($q['xp_reward'])?> XP</small></div><span class="status <?=e($q['status'])?>"><?=e(status_label($q['status']))?></span><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$q['id']?>"><?php if($q['status']!=='completed'&&$q['status']!=='cancelled'):?><button class="small-btn" name="action" value="cancel">Cancel</button><?php endif;?><button class="small-btn danger-text" name="action" value="delete" onclick="return confirm('Delete this quest?')">Delete</button></form></div><?php endforeach;?></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
